        for fi in s['findings'][:3]: print("  FIND:", fi[:280])
    p=s.get('proposal') or ''
    if p:
        print("  PROPOSAL (first 900 chars):"); print(p[:900])
    if s.get('metrics'): print("  METRICS:", s['metrics'])
    if s.get('verdict'): print("  VERDICT:", s['verdict'][:240])
PY

