        print(f"  {a:4} n={m['real'][2]}  real={m['real'][0]:>8.0f} (spread {m['real'][1]:>6.0f})"
              f"  total={m['total'][0]:>8.0f}  out={m['out'][0]:>6.0f}"
              f"  ${m['cost'][0]:.4f}  turns={m['turns'][0]:.1f}")
    if per.get("base") and per.get("lean"):
