"""Score the multi-arm lean-mode bench. Every arm vs the SAME base. All metrics, mean+spread,
noise gate (delta must exceed the arms' own run-to-run spread to count as signal)."""
import glob, json, os, statistics as st, sys

OUT = sys.argv[1] if len(sys.argv) > 1 else "results2"
TASKS = ["T1", "T2", "T3", "T4"]
ARMS = ["base", "lean1", "lean2", "lean3"]
LABEL = {"T1": "T1 locate", "T2": "T2 impact", "T3": "T3 multi-hop", "T4": "T4 named-file CONTROL"}

def load(t, a):
    rows = []
    for f in sorted(glob.glob(os.path.join(OUT, f"{t}-{a}-r*.json"))):
        try: d = json.load(open(f))
        except Exception: continue
        u = d.get("usage", {}) or {}
        i, o = u.get("input_tokens", 0) or 0, u.get("output_tokens", 0) or 0
        cc, cr = u.get("cache_creation_input_tokens", 0) or 0, u.get("cache_read_input_tokens", 0) or 0
        rows.append({"real": cc + i + o, "total": cc + i + o + cr, "out": o,
                     "cost": float(d.get("total_cost_usd") or 0), "turns": d.get("num_turns") or 0,
                     "err": bool(d.get("is_error")), "api": d.get("api_error_status"),
                     "file": os.path.basename(f)})
    return rows

def m(rows, k):
    v = [r[k] for r in rows if r.get(k) is not None]
    return (st.mean(v), max(v) - min(v), len(v)) if v else (None, None, 0)

def pct(b, l): return None if not b else (l - b) / b * 100.0

warn, agg = [], {a: {k: [] for k in ("real", "total", "out", "cost", "turns")} for a in ARMS}
print(f"lean-mode multi-arm bench — {OUT}\n")

for t in TASKS:
    print(LABEL[t])
    per = {}
    for a in ARMS:
        rows = load(t, a)
        if not rows: print(f"  {a:6} NO DATA"); continue
        for r in rows:
            if r["err"] or r["api"]: warn.append(f"{t}/{a} {r['file']}: err={r['err']} api={r['api']}")
        s = {k: m(rows, k) for k in ("real", "total", "out", "cost", "turns")}
        if s["real"][0] is None: continue
        per[a] = s
        for k in agg[a]:
            if s[k][0] is not None: agg[a][k].append(s[k][0])
        line = (f"  {a:6} n={s['real'][2]} real={s['real'][0]:>7.0f}(±{s['real'][1]:>5.0f})"
