            d = pct(b["real"][0], s["real"][0])
            spread = max(b["real"][1], s["real"][1]); dabs = abs(s["real"][0] - b["real"][0])
            line += f"  Δreal {d:+.1f}% {'SIG' if dabs > spread else 'noise'}"
        print(line)
    print()

print("AGGREGATE (unweighted mean of per-task means)")
base = {k: st.mean(agg["base"][k]) for k in agg["base"] if agg["base"][k]}
for a in ARMS:
    if not agg[a]["real"]: continue
    v = {k: st.mean(agg[a][k]) for k in agg[a] if agg[a][k]}
    row = f"  {a:6} real={v['real']:>7.0f} total={v['total']:>8.0f} out={v['out']:>5.0f} ${v['cost']:.4f} turns={v['turns']:.1f}"
    if a != "base":
        row += (f"   Δreal {pct(base['real'], v['real']):+.1f}%"
                f"  Δtotal {pct(base['total'], v['total']):+.1f}%"
                f"  Δout {pct(base['out'], v['out']):+.1f}%"
                f"  Δcost {pct(base['cost'], v['cost']):+.1f}%")
    print(row)

print("\nGOAL: Δreal <= -30%")
for a in ARMS:
    if a == "base" or not agg[a]["real"]: continue
    d = pct(base["real"], st.mean(agg[a]["real"]))
    print(f"  {a:6} {d:+.1f}%  {'*** TARGET MET ***' if d <= -30 else 'short of -30%'}")

print("\n" + ("WARNINGS:\n  " + "\n  ".join(warn) if warn else "no errored runs."))

